import { defineCollection } from 'astro:content';
import { z } from 'astro/zod';
import { docsLoader } from '@astrojs/starlight/loaders';
import { docsSchema } from '@astrojs/starlight/schema';

// Pages generated by starlight-openapi have no description of their own; src/route-data.ts gives them one, and
// scripts/check-build.mjs fails the build if any page ends up without its own meta description.
export const collections = {
  docs: defineCollection({
    loader: docsLoader(),
    schema: docsSchema({ extend: z.object({ description: z.string().min(50).max(155).optional() }) }),
  }),
};
